def resolve(path, cwd, links):
    # Check if path is absolute
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                # Move to parent
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component
        if current == '/':
            current = '/' + comp
        else:
            current = current + '/' + comp

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[current]

            # Parse the target
            if target.startswith('/'):
                # Absolute target
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Relative target - relative to the directory containing the link
                if current == '/':
                    current = '/'
                else:
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                target_components = target.split('/')

            # Replace remaining components with target components + rest
            components = target_components + components[i+1:]
            i = 0
        else:
            i += 1

    # Return result without trailing slash, except for '/'
    if current == '/':
        return '/'
    else:
        return current

